def greedy_wedge(G, A):
    S = set(A)
    while True:
        found = False
        for v in range(G.V):
            if v not in S and G.cut_weight(S | {v}) <= G.cut_weight(S):
                S.add(v)
                found = True
                break
        if not found:
            break
    return S

def rt_singleton_check(n, k, d):
    s_ent = (n - k) / 2.0
    is_mds = (2*d + k == n + 2)
    gap = (n + 2) - (2*d + k)
    return {'singleton_entropy': s_ent, 'is_mds': is_mds, 'gap': gap}
